<script setup>
import { computed, onMounted, ref } from 'vue'; import { ArrowRight, Minus, Plus, ShoppingBag, Trash2 } from 'lucide-vue-next'; import { RouterLink } from 'vue-router'; import { useCartStore } from '../stores/cart';
const cart = useCartStore(); const selected = ref([]); const error = ref(''); const selectedItems = computed(() => cart.items.filter(item => selected.value.includes(item.id))); const subtotal = computed(() => selectedItems.value.reduce((sum, item) => sum + Number(item.product.price) * item.quantity, 0));
onMounted(async () => { await cart.fetch(); selected.value = cart.items.map(item => item.id); });
async function quantity(item, value) { try { await cart.setQuantity(item, value); } catch (e) { error.value = e.response?.data?.message || 'Quantity could not be updated.'; } }
async function remove(item) { try { await cart.remove(item); selected.value = selected.value.filter(id => id !== item.id); } catch { error.value = 'Item could not be removed.'; } }
</script>
<template><section class="container page-section"><div class="section-heading"><div><p class="kicker">YOUR SELECTION</p><h1>Shopping cart</h1></div><span class="muted">{{ cart.count }} items</span></div><div v-if="cart.loading" class="state">Loading your cart...</div><div v-else-if="!cart.items.length" class="state empty-cart"><ShoppingBag :size="38" /><h2>Your cart is waiting.</h2><p>Add something excellent to get started.</p><RouterLink class="button button-dark" to="/products">Browse hardware <ArrowRight :size="16" /></RouterLink></div><div v-else class="cart-layout"><div class="cart-items"><p v-if="error" class="form-error">{{ error }}</p><TransitionGroup name="list"><article v-for="item in cart.items" :key="item.id" class="cart-item"><input v-model="selected" type="checkbox" :value="item.id" aria-label="Select item"><img v-if="item.product.image_url" :src="item.product.image_url" :alt="item.product.name"><div v-else class="cart-thumb">N</div><div class="cart-item-copy"><p class="eyebrow">{{ item.product.name }}</p><strong>${{ Number(item.product.price).toLocaleString() }}</strong><span>{{ item.product.stock }} in stock</span></div><div class="quantity"><button :disabled="item.quantity <= 1" @click="quantity(item, item.quantity - 1)"><Minus :size="14" /></button><span>{{ item.quantity }}</span><button :disabled="item.quantity >= item.product.stock" @click="quantity(item, item.quantity + 1)"><Plus :size="14" /></button></div><button class="icon-action muted-action" title="Remove item" @click="remove(item)"><Trash2 :size="17" /></button></article></TransitionGroup></div><aside class="summary"><h3>Order summary</h3><div><span>Selected items</span><strong>${{ subtotal.toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><div><span>Shipping</span><strong>Calculated at fulfillment</strong></div><hr><div class="summary-total"><span>Total</span><strong>${{ subtotal.toLocaleString(undefined, { minimumFractionDigits: 2 }) }}</strong></div><RouterLink class="button button-accent full-button" :class="{ disabled: !selected.length }" to="/checkout">Continue to checkout <ArrowRight :size="16" /></RouterLink><small>The server calculates the final order total when placed.</small></aside></div></section></template>
